package kafka

import (
	"context"

	catalog_eventsv1 "github.com/Sokol111/ecommerce-catalog-service-api/gen/go/catalog/events/v1"
	"github.com/Sokol111/ecommerce-commons/pkg/core/logger"
	image_eventsv1 "github.com/Sokol111/ecommerce-image-service-api/gen/go/image/events/v1"
	"github.com/Sokol111/ecommerce-product-query-service/internal/application/productview"
	"github.com/samber/lo"
	"go.uber.org/zap"
)

type ProductHandler struct {
	upsertHandler      productview.UpsertProductCommandHandler
	deleteHandler      productview.DeleteProductCommandHandler
	updateImageHandler productview.UpdateImageURLsCommandHandler
}

func NewProductHandler(
	upsertHandler productview.UpsertProductCommandHandler,
	deleteHandler productview.DeleteProductCommandHandler,
	updateImageHandler productview.UpdateImageURLsCommandHandler,
) *ProductHandler {
	return &ProductHandler{
		upsertHandler:      upsertHandler,
		deleteHandler:      deleteHandler,
		updateImageHandler: updateImageHandler,
	}
}

func (h *ProductHandler) HandleProductUpdated(ctx context.Context, e *catalog_eventsv1.ProductUpdatedEvent) error {
	attributes, attrs := mapAttributes(e.Attributes)

	view := productview.NewProductView(
		e.ProductId,
		e.Version,
		e.Name,
		e.Description,
		e.Price,
		e.Quantity,
		e.ImageId,
		e.CategoryId,
		e.Enabled,
		e.CreatedAt.AsTime().UTC(),
		e.ModifiedAt.AsTime().UTC(),
		attributes,
		attrs,
	)

	if err := h.upsertHandler.Handle(ctx, productview.UpsertProductCommand{Product: view}); err != nil {
		return err
	}

	h.log(ctx).Debug("product view updated",
		zap.String("productID", e.ProductId),
		zap.Int64("version", e.Version))

	return nil
}

// mapAttributes converts event attributes to domain attributes and builds attrs map.
func mapAttributes(eventAttrs []*catalog_eventsv1.AttributeValue) ([]productview.AttributeValue, map[string]any) {
	if len(eventAttrs) == 0 {
		return nil, nil
	}
	return lo.Map(eventAttrs, mapAttribute), buildAttrsMap(eventAttrs)
}

// mapAttribute converts a single event attribute to a domain attribute.
func mapAttribute(attr *catalog_eventsv1.AttributeValue, _ int) productview.AttributeValue {
	result := productview.AttributeValue{
		AttributeID: attr.AttributeId,
		Slug:        attr.AttributeSlug,
	}
	switch v := attr.Value.(type) {
	case *catalog_eventsv1.AttributeValue_OptionSlugValue:
		result.OptionSlugValue = &v.OptionSlugValue
	case *catalog_eventsv1.AttributeValue_OptionSlugValues:
		if v.OptionSlugValues != nil {
			result.OptionSlugValues = v.OptionSlugValues.Values
		}
	case *catalog_eventsv1.AttributeValue_NumericValue:
		result.NumericValue = &v.NumericValue
	case *catalog_eventsv1.AttributeValue_TextValue:
		result.TextValue = &v.TextValue
	case *catalog_eventsv1.AttributeValue_BooleanValue:
		result.BooleanValue = &v.BooleanValue
	}
	return result
}

// buildAttrsMap builds a denormalized attributes map for filtering (slug -> value).
func buildAttrsMap(eventAttrs []*catalog_eventsv1.AttributeValue) map[string]any {
	attrs := make(map[string]any, len(eventAttrs))
	for _, attr := range eventAttrs {
		if attr.AttributeSlug == "" {
			continue
		}
		switch v := attr.Value.(type) {
		case *catalog_eventsv1.AttributeValue_NumericValue:
			attrs[attr.AttributeSlug] = v.NumericValue
		case *catalog_eventsv1.AttributeValue_OptionSlugValues:
			if v.OptionSlugValues != nil && len(v.OptionSlugValues.Values) > 0 {
				attrs[attr.AttributeSlug] = v.OptionSlugValues.Values
			}
		case *catalog_eventsv1.AttributeValue_OptionSlugValue:
			attrs[attr.AttributeSlug] = v.OptionSlugValue
		case *catalog_eventsv1.AttributeValue_TextValue:
			attrs[attr.AttributeSlug] = v.TextValue
		case *catalog_eventsv1.AttributeValue_BooleanValue:
			attrs[attr.AttributeSlug] = v.BooleanValue
		}
	}
	return attrs
}

func (h *ProductHandler) HandleProductDeleted(ctx context.Context, e *catalog_eventsv1.ProductDeletedEvent) error {
	cmd := productview.DeleteProductCommand{ProductID: e.ProductId}
	if err := h.deleteHandler.Handle(ctx, cmd); err != nil {
		return err
	}

	h.log(ctx).Debug("product view deleted",
		zap.String("productID", e.ProductId))

	return nil
}

func (h *ProductHandler) HandleProductImagePromoted(ctx context.Context, e *image_eventsv1.ProductImagePromotedEvent) error {
	cmd := productview.UpdateImageURLsCommand{
		ProductID:     e.ProductId,
		ImageID:       e.ImageId,
		SmallImageURL: e.SmallImageUrl,
		LargeImageURL: e.LargeImageUrl,
	}
	if err := h.updateImageHandler.Handle(ctx, cmd); err != nil {
		return err
	}

	h.log(ctx).Debug("product image URLs updated",
		zap.String("productID", e.ProductId),
		zap.String("imageID", e.ImageId))

	return nil
}

func (h *ProductHandler) log(ctx context.Context) *zap.Logger {
	return logger.Get(ctx).With(zap.String("component", "product-handler"))
}

